from pathlib import Path
p=Path(__file__).resolve().parents[1]
def replace(file,old,new):
    f=p/file;s=f.read_text(encoding='utf8');assert s.count(old)==1,(file,s.count(old));f.write_text(s.replace(old,new),encoding='utf8')
